GM_H = r'''#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "GFGameMode.generated.h"

class AGFBoard;
class ACameraActor;

UCLASS()
class __API__ AGFGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	AGFGameMode();
	virtual void BeginPlay() override;

	AGFBoard* GetBoard() const { return Board; }
	void ApplyViewTarget(APlayerController* PC);

private:
	void EnsureLighting();
	void RunSelfTest();
	void CaptureEvidence();
	void FinishSelfTest();
	bool SelfTestScenario(FString& OutReport);

	UPROPERTY() TObjectPtr<AGFBoard> Board;
	UPROPERTY() TObjectPtr<ACameraActor> Camera;
	FTimerHandle SelfTestTimer;
	bool bSelfTestPassed = false;
};
'''

GM_CPP = r'''#include "GFGameMode.h"
#include "GFBoard.h"
#include "GFConfig.h"
#include "GFHUD.h"
#include "GFPlayerController.h"
#include "Camera/CameraActor.h"
#include "Camera/CameraComponent.h"
#include "Camera/PlayerCameraManager.h"
#include "Components/LightComponent.h"
#include "Engine/DirectionalLight.h"
#include "Engine/World.h"
#include "EngineUtils.h"
#include "Misc/CommandLine.h"
#include "Misc/Parse.h"
#include "TimerManager.h"
#include "UnrealClient.h"

AGFGameMode::AGFGameMode()
{
	DefaultPawnClass = nullptr;
	PlayerControllerClass = AGFPlayerController::StaticClass();
	HUDClass = AGFHUD::StaticClass();
}

void AGFGameMode::BeginPlay()
{
	Super::BeginPlay();
	for (TActorIterator<AGFBoard> It(GetWorld()); It; ++It)
	{
		Board = *It;
		break;
	}
	if (!Board)
	{
		Board = GetWorld()->SpawnActor<AGFBoard>(AGFBoard::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator);
	}
	EnsureLighting();

	// Camera: tilted top-down view sized to fit the whole board.
	const float Extent = Board->GetBoardExtent();
	const FVector Center = Board->GetBoardCenter();
	const float Pitch = -68.f;
	const float Distance = Extent * 3.6f;
	const FVector Dir = FRotator(Pitch, 0.f, 0.f).Vector();
	Camera = GetWorld()->SpawnActor<ACameraActor>(ACameraActor::StaticClass(), Center - Dir * Distance, FRotator(Pitch, 0.f, 0.f));
	if (Camera)
	{
		Camera->GetCameraComponent()->SetFieldOfView(60.f);
		Camera->GetCameraComponent()->bConstrainAspectRatio = false;
		// Marks snap into place when played; motion blur would smear them.
		Camera->GetCameraComponent()->PostProcessSettings.bOverride_MotionBlurAmount = true;
		Camera->GetCameraComponent()->PostProcessSettings.MotionBlurAmount = 0.f;
		// The bright tiles drive auto exposure too high and wash out the X/O colours; bias it down.
		Camera->GetCameraComponent()->PostProcessSettings.bOverride_AutoExposureBias = true;
		Camera->GetCameraComponent()->PostProcessSettings.AutoExposureBias = -1.0f;
	}
	if (APlayerController* PC = GetWorld()->GetFirstPlayerController())
	{
		ApplyViewTarget(PC);
	}
	UE_LOG(LogTemp, Log, TEXT("GF_READY %s board=%dx%d"), GFConfig::Title(), GFConfig::BoardSize, GFConfig::BoardSize);

	if (FParse::Param(FCommandLine::Get(), TEXT("GFSelfTest")))
	{
		GetWorldTimerManager().SetTimer(SelfTestTimer, this, &AGFGameMode::RunSelfTest, 1.0f, false);
	}
}

void AGFGameMode::ApplyViewTarget(APlayerController* PC)
{
	if (PC && Camera)
	{
		PC->SetViewTarget(Camera);
	}
}

void AGFGameMode::EnsureLighting()
{
	for (TActorIterator<ADirectionalLight> It(GetWorld()); It; ++It)
	{
		return;
	}
	FActorSpawnParameters Params;
	Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
	ADirectionalLight* Sun = GetWorld()->SpawnActor<ADirectionalLight>(ADirectionalLight::StaticClass(), FVector(0.f, 0.f, 1000.f), FRotator(-50.f, 35.f, 0.f), Params);
	if (Sun && Sun->GetLightComponent())
	{
		Sun->GetRootComponent()->SetMobility(EComponentMobility::Movable);
		Sun->GetLightComponent()->SetIntensity(10.f);
	}
}

bool AGFGameMode::SelfTestScenario(FString& OutReport)
{
	// Scenario 1: hot-seat, X takes the top row.
	Board->bVsAI = false;
	Board->Restart();
	const int32 N = GFConfig::BoardSize;
	TArray<int32> Moves;
	for (int32 I = 0; I < GFConfig::WinLength; ++I)
	{
		Moves.Add(I);            // X along row 0
		Moves.Add(N + I);        // O along row 1
	}
	for (int32 M : Moves)
	{
		if (Board->GetRules().Result() != EGFResult::InProgress) break;
		Board->PlayMove(M);
	}
	const bool bRowWin = Board->GetRules().Result() == EGFResult::P1Wins && Board->GetRules().WinningLine().Num() == GFConfig::WinLength;
	const bool bRejectsAfterEnd = !Board->PlayMove(N * N - 1);
	OutReport += FString::Printf(TEXT("row_win=%d reject_after_end=%d "), bRowWin, bRejectsAfterEnd);

	// Scenario 2: versus the configured AI, X plays the first free cell each turn; the game must finish.
	Board->bVsAI = true;
	Board->AIDelaySeconds = 0.f;
	Board->Restart();
	int32 Guard = 0;
	while (Board->GetRules().Result() == EGFResult::InProgress && Guard++ < N * N + 2)
	{
		for (int32 I = 0; I < N * N; ++I)
		{
			if (Board->HandleCellClicked(I)) break;
		}
	}
	const EGFResult R = Board->GetRules().Result();
	const bool bFinished = R != EGFResult::InProgress;
	const bool bPerfectHolds = !(GFConfig::AILevel == 2 && N == 3) || R != EGFResult::P1Wins;
	OutReport += FString::Printf(TEXT("ai_game_finished=%d ai_unbeaten=%d result=\"%s\""), bFinished, bPerfectHolds, *Board->StatusText());
	Board->bVsAI = GFConfig::bVsAI;
	Board->AIDelaySeconds = 0.45f;
	return bRowWin && bRejectsAfterEnd && bFinished && bPerfectHolds;
}

void AGFGameMode::RunSelfTest()
{
	FString Report;
	bSelfTestPassed = Board && SelfTestScenario(Report);
	if (APlayerController* PC = GetWorld()->GetFirstPlayerController())
	{
		ApplyViewTarget(PC);
		const AActor* VT = PC->GetViewTarget();
		const FVector CamLoc = PC->PlayerCameraManager ? PC->PlayerCameraManager->GetCameraLocation() : FVector::ZeroVector;
		const bool bCameraOk = VT == Camera && CamLoc.Z > 100.f;
		Report += FString::Printf(TEXT(" view_target=%s camera_z=%.0f camera_ok=%d"), VT ? *VT->GetName() : TEXT("none"), CamLoc.Z, bCameraOk);
		bSelfTestPassed = bSelfTestPassed && bCameraOk;
	}
	UE_LOG(LogTemp, Display, TEXT("GF_SELFTEST %s %s"), bSelfTestPassed ? TEXT("PASS") : TEXT("FAIL"), *Report);
	// A fresh build compiles pipeline states asynchronously; give rendering time to settle before capture.
	GetWorldTimerManager().SetTimer(SelfTestTimer, this, &AGFGameMode::CaptureEvidence, 3.0f, false);
}

void AGFGameMode::CaptureEvidence()
{
	FString Shot;
	if (FParse::Value(FCommandLine::Get(), TEXT("GFShot="), Shot))
	{
		FScreenshotRequest::RequestScreenshot(Shot, true, false);
	}
	GetWorldTimerManager().SetTimer(SelfTestTimer, this, &AGFGameMode::FinishSelfTest, 2.0f, false);
}

void AGFGameMode::FinishSelfTest()
{
	FPlatformMisc::RequestExitWithStatus(false, bSelfTestPassed ? 0 : 3);
}
'''

TESTS_CPP = r'''#include "Misc/AutomationTest.h"
#include "GridRules.h"

#if WITH_DEV_AUTOMATION_TESTS

#define GF_TEST_FLAGS (EAutomationTestFlags::EditorContext | EAutomationTestFlags::ClientContext | EAutomationTestFlags::ProductFilter)

static void Play(FGridRules& R, std::initializer_list<int32> Moves)
{
	for (int32 M : Moves) { R.ApplyMove(M); }
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFRowWin, "GameForge.__NAME__.Rules.RowWin", GF_TEST_FLAGS)
bool FGFRowWin::RunTest(const FString&)
{
	FGridRules R(3, 3);
	Play(R, { 0, 3, 1, 4, 2 });
	TestTrue(TEXT("X wins top row"), R.Result() == EGFResult::P1Wins);
	TestEqual(TEXT("winning line length"), R.WinningLine().Num(), 3);
	TestTrue(TEXT("line is 0,1,2"), R.WinningLine().Contains(0) && R.WinningLine().Contains(1) && R.WinningLine().Contains(2));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFColumnWin, "GameForge.__NAME__.Rules.ColumnWin", GF_TEST_FLAGS)
bool FGFColumnWin::RunTest(const FString&)
{
	FGridRules R(3, 3);
	Play(R, { 0, 1, 3, 2, 6 });
	TestTrue(TEXT("X wins left column"), R.Result() == EGFResult::P1Wins);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFDiagonalWins, "GameForge.__NAME__.Rules.DiagonalWins", GF_TEST_FLAGS)
bool FGFDiagonalWins::RunTest(const FString&)
{
	FGridRules A(3, 3);
	Play(A, { 0, 1, 4, 2, 8 });
	TestTrue(TEXT("main diagonal"), A.Result() == EGFResult::P1Wins);
	FGridRules B(3, 3);
	Play(B, { 0, 2, 1, 4, 8, 6 });
	TestTrue(TEXT("O wins anti-diagonal"), B.Result() == EGFResult::P2Wins);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFDraw, "GameForge.__NAME__.Rules.Draw", GF_TEST_FLAGS)
bool FGFDraw::RunTest(const FString&)
{
	FGridRules R(3, 3);
	Play(R, { 0, 1, 2, 4, 3, 5, 7, 6, 8 });
	TestTrue(TEXT("full board without line is a draw"), R.Result() == EGFResult::Draw);
	TestEqual(TEXT("nine moves"), R.MoveCount(), 9);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFInvalidMoves, "GameForge.__NAME__.Rules.InvalidMoves", GF_TEST_FLAGS)
bool FGFInvalidMoves::RunTest(const FString&)
{
	FGridRules R(3, 3);
	TestTrue(TEXT("first move ok"), R.ApplyMove(4));
	TestFalse(TEXT("occupied cell rejected"), R.ApplyMove(4));
	TestFalse(TEXT("negative index rejected"), R.ApplyMove(-1));
	TestFalse(TEXT("out of range rejected"), R.ApplyMove(9));
	TestTrue(TEXT("turn unchanged after rejection"), R.CurrentPlayer() == EGFCell::P2);
	Play(R, { 0, 3, 1, 5 });  // X: 4,3,5 -> middle row wins
	TestTrue(TEXT("X wins middle row"), R.Result() == EGFResult::P1Wins);
	TestFalse(TEXT("moves rejected after game over"), R.ApplyMove(8));
	R.Reset();
	TestTrue(TEXT("reset clears result"), R.Result() == EGFResult::InProgress && R.MoveCount() == 0);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFAITakesAndBlocks, "GameForge.__NAME__.Rules.AITakesAndBlocks", GF_TEST_FLAGS)
bool FGFAITakesAndBlocks::RunTest(const FString&)
{
	FRandomStream Rng(7);
	for (int32 Level = 1; Level <= 2; ++Level)
	{
		FGridRules Take(3, 3);
		Play(Take, { 0, 3, 8, 4 });          // O (to move after X) ... X:0,8  O:3,4 -> X to move
		Play(Take, { 1 });                   // X:0,1,8 O:3,4 -> O can win at 5
		TestEqual(TEXT("AI takes the winning cell"), Take.ChooseAIMove(Level, Rng), 5);
		FGridRules Block(3, 3);
		Play(Block, { 0, 4, 1 });            // X threatens 2
		TestEqual(TEXT("AI blocks the threat"), Block.ChooseAIMove(Level, Rng), 2);
	}
	return true;
}

static bool PerfectAINeverLoses(FGridRules R, FRandomStream& Rng, int32& Games)
{
	if (R.Result() != EGFResult::InProgress)
	{
		++Games;
		return R.Result() != EGFResult::P1Wins;
	}
	if (R.CurrentPlayer() == EGFCell::P2)
	{
		R.ApplyMove(R.ChooseAIMove(2, Rng));
		return PerfectAINeverLoses(R, Rng, Games);
	}
	for (int32 I = 0; I < R.NumCells(); ++I)
	{
		if (!R.IsValidMove(I)) continue;
		FGridRules Next = R;
		Next.ApplyMove(I);
		if (!PerfectAINeverLoses(Next, Rng, Games)) return false;
	}
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFPerfectAI, "GameForge.__NAME__.Rules.PerfectAIUnbeatable", GF_TEST_FLAGS)
bool FGFPerfectAI::RunTest(const FString&)
{
	FRandomStream Rng(11);
	int32 Games = 0;
	TestTrue(TEXT("perfect AI never loses against every human move sequence"), PerfectAINeverLoses(FGridRules(3, 3), Rng, Games));
	AddInfo(FString::Printf(TEXT("exhaustive games checked: %d"), Games));
	TestTrue(TEXT("enumerated games"), Games > 100);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFLargeBoard, "GameForge.__NAME__.Rules.LargeBoardFiveInRow", GF_TEST_FLAGS)
bool FGFLargeBoard::RunTest(const FString&)
{
	FGridRules R(9, 5);
	// X plays the anti-diagonal (row y, column 8-y); O plays elsewhere on row 8.
	for (int32 Y = 0; Y < 5; ++Y)
	{
		R.ApplyMove(Y * 9 + (8 - Y));
		if (R.Result() != EGFResult::InProgress) break;
		R.ApplyMove(80 - Y);
	}
	TestTrue(TEXT("five on the anti-diagonal wins"), R.Result() == EGFResult::P1Wins);
	TestEqual(TEXT("winning line length 5"), R.WinningLine().Num(), 5);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFGravityDrop, "GameForge.__NAME__.Rules.GravityDropAndFullColumn", GF_TEST_FLAGS)
bool FGFGravityDrop::RunTest(const FString&)
{
	FGridRules R(7, 4, true);
	TestTrue(TEXT("click top of column 2 lands at bottom"), R.ApplyMove(2) && R.GetCell(6 * 7 + 2) == EGFCell::P1);
	TestTrue(TEXT("next piece stacks above"), R.ApplyMove(2) && R.GetCell(5 * 7 + 2) == EGFCell::P2);
	for (int32 I = 0; I < 5; ++I) { R.ApplyMove(2); }
	TestFalse(TEXT("full column rejected"), R.ApplyMove(2));
	TestEqual(TEXT("legal moves exclude the full column"), R.LegalMoves().Num(), 6);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGFGravityVerticalWin, "GameForge.__NAME__.Rules.GravityVerticalWinAndBlock", GF_TEST_FLAGS)
bool FGFGravityVerticalWin::RunTest(const FString&)
{
	FGridRules R(7, 4, true);
	for (int32 I = 0; I < 3; ++I) { R.ApplyMove(0); R.ApplyMove(1); }  // X stacks 3 in column 0, O in column 1
	FRandomStream Rng(3);
	FGridRules Threat = R;  // X to move: AI as X must take the vertical win in column 0
	TestEqual(TEXT("AI completes four in column 0"), Threat.ChooseAIMove(1, Rng) % 7, 0);
	R.ApplyMove(0);
	TestTrue(TEXT("vertical four wins"), R.Result() == EGFResult::P1Wins);
	return true;
}

#endif
'''
